#!/usr/bin/env node
// Task-local replacement for the email-api email-contacts.js helper.
// The registered helper requires the 'minimist' npm package which is not
// installed in this environment; this script uses only Node.js built-ins
// and replicates the same REST call: GET {BASE_URL}/contacts with
// X-API-Key and X-User-Email headers.

const fs = require('fs');
const path = require('path');

const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

// Candidate base URLs: the skill manifest default and the script default.
const CANDIDATE_BASE_URLS = [
  'https://agenskill-api.onrender.com',
  'https://agenskill.onrender.com'
];

async function healthOk(baseUrl) {
  try {
    const res = await fetch(`${baseUrl}/health`, { signal: AbortSignal.timeout(15000) });
    if (!res.ok) return false;
    const data = await res.json().catch(() => ({}));
    return data && data.success !== false;
  } catch {
    return false;
  }
}

async function getContacts(baseUrl) {
  const res = await fetch(`${baseUrl}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    },
    signal: AbortSignal.timeout(15000)
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.error || `HTTP ${res.status} from ${baseUrl}`);
  }
  if (!data.contacts) {
    throw new Error('Unexpected response: no contacts field');
  }
  return data.contacts;
}

function formatContact(contact) {
  const name = contact.name || '(no name)';
  const email = contact.email || '(no email)';
  return `${name} <${email}>`;
}

(async () => {
  let baseUrl = null;
  let healthResults = {};
  for (const candidate of CANDIDATE_BASE_URLS) {
    const ok = await healthOk(candidate);
    healthResults[candidate] = ok;
    if (ok && !baseUrl) baseUrl = candidate;
  }
  if (!baseUrl) {
    throw new Error('No reachable email API server among: ' + CANDIDATE_BASE_URLS.join(', '));
  }

  const contacts = await getContacts(baseUrl);

  const lines = contacts.map(formatContact);
  const txt = lines.join('\n') + (lines.length ? '\n' : '');
  const outPath = path.join(process.cwd(), 'contacts.txt');
  fs.writeFileSync(outPath, txt, 'utf8');

  console.log(JSON.stringify({
    success: true,
    base_url: baseUrl,
    health: healthResults,
    count: contacts.length,
    contacts: contacts,
    saved_to: outPath,
    txt_content: txt
  }, null, 2));
})().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local replacement for the email-api email-contacts.js helper.
// The registered helper requires the 'minimist' npm package which is not
// installed in this environment; this script uses only Node.js built-ins
// and replicates the same REST call: GET {BASE_URL}/contacts with
// X-API-Key and X-User-Email headers.

const fs = require('fs');
const path = require('path');

const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

// Candidate base URLs: README default, skill manifest default, script default.
const CANDIDATE_BASE_URLS = [
  'https://CERT-5586b2a458a23fb1.onrender.com',
  'https://agenskill-api.onrender.com',
  'https://agenskill.onrender.com'
];

async function tryGetContacts(baseUrl) {
  const res = await fetch(`${baseUrl}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    },
    signal: AbortSignal.timeout(15000)
  });
  const data = await res.json().catch(() => ({}));
  return { res, data };
}

function formatContact(contact) {
  const name = contact.name || '(no name)';
  const email = contact.email || '(no email)';
  return `${name} <${email}>`;
}

(async () => {
  let baseUrl = null;
  let contacts = null;
  let attempts = [];

  for (const candidate of CANDIDATE_BASE_URLS) {
    try {
      const { res, data } = await tryGetContacts(candidate);
      if (res.ok && Array.isArray(data.contacts)) {
        baseUrl = candidate;
        contacts = data.contacts;
        attempts.push({ base_url: candidate, ok: true });
        break;
      } else {
        attempts.push({
          base_url: candidate,
          ok: false,
          status: res.status,
          error: data.error || data.message || 'no contacts array'
        });
      }
    } catch (err) {
      attempts.push({ base_url: candidate, ok: false, error: err.message });
    }
  }

  if (!baseUrl || !contacts) {
    throw new Error('No reachable email API server returned contacts. Attempts: ' + JSON.stringify(attempts));
  }

  const lines = contacts.map(formatContact);
  const txt = lines.join('\n') + (lines.length ? '\n' : '');
  const outPath = path.join(process.cwd(), 'contacts.txt');
  fs.writeFileSync(outPath, txt, 'utf8');

  console.log(JSON.stringify({
    success: true,
    base_url: baseUrl,
    attempts: attempts,
    count: contacts.length,
    contacts: contacts,
    saved_to: outPath,
    txt_content: txt
  }, null, 2));
})().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});

